import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdirSync, mkdtempSync, rmSync, symlinkSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import {
  classifyAiPolicy, cloneEnv, detectAiTrailer, detectProfile, detectsCla, detectsDco, outOfScopePaths, profilePromptNotes, refuseIssue, setupKey, setupPlan,
} from "../contrib-profile";

test("classifyAiPolicy: bans, disclosure requirements, and silence", () => {
  const bans = [
    "We do not accept contributions generated by AI tools or LLMs.",
    "AI-generated pull requests will be closed without review.".replace("will be closed without review", "are not accepted"),
    "This project prohibits AI-generated code in any form.",
    "Contributions written by ChatGPT, Copilot or similar are not allowed.",
  ];
  for (const text of bans) assert.equal(classifyAiPolicy(text).stance, "ban", text);
  const disclose = [
    "Disclose in PR: Always mention when a pull request includes AI-generated code.",
    "- [ ] AI assistance was used during the creation of this PR.",
    "If you used an LLM, you must state this in the PR description.",
  ];
  for (const text of disclose) assert.equal(classifyAiPolicy(text).stance, "disclose", text);
  for (const text of ["Please add tests.", "We use a CLA bot.", "Pure code-agent PRs are not allowed. A human must review."]) {
    assert.notEqual(classifyAiPolicy(text).stance, "ban", text);
  }
  assert.match(classifyAiPolicy("Intro.\nWe do not accept AI-generated patches. Thanks.").excerpt!, /^We do not accept AI-generated patches\./);
});

test("DCO, CLA and trailer detection", () => {
  assert.ok(detectsDco("Commits must include a `Signed-off-by:` header"));
  assert.ok(detectsDco("we follow the Developer Certificate of Origin"));
  assert.ok(!detectsDco("Please sign your work emotionally."));
  assert.ok(detectsCla("You must sign the Contributor License Agreement"));
  assert.ok(!detectsCla("clarity matters"));
  assert.equal(detectAiTrailer("Co-authored-by: Claude\n(other projects use Assisted-by: or Generated-by:)"), "Assisted-by");
  assert.equal(detectAiTrailer("Co-authored-by: GitHub Copilot"), "Co-authored-by");
  assert.equal(detectAiTrailer("Co-authored-by: Jane <j@x>"), null);
});

function fixture(files: Record<string, string>): string {
  const dir = mkdtempSync(path.join(tmpdir(), "opensrcer-profile-"));
  for (const [rel, text] of Object.entries(files)) {
    mkdirSync(path.dirname(path.join(dir, rel)), { recursive: true });
    writeFileSync(path.join(dir, rel), text);
  }
  return dir;
}

test("detectProfile reads the repository's own files", () => {
  const dir = fixture({
    "docs/contributing/README.md": "### DCO\nCommits must include a `Signed-off-by:` header.\nAlways mention when a pull request includes AI-generated code. Use Assisted-by: trailers.",
    ".github/PULL_REQUEST_TEMPLATE.md": "## Summary\n\n## How did you test this change?\n",
    "AGENTS.md": "Run the duplicate checks first.",
  });
  try {
    const p = detectProfile(dir, "someone/thing");
    assert.equal(p.dco, true);
    assert.equal(p.cla, null);
    assert.match(p.prTemplate!, /How did you test/);
    assert.match(p.agentInstructions!, /duplicate checks/);
    assert.equal(p.aiPolicy.stance, "disclose");
    assert.equal(p.aiPolicy.source, "docs/contributing/README.md");
    assert.equal(p.aiTrailer, "Assisted-by");
    const notes = profilePromptNotes(p);
    assert.match(notes, /<pr-template untrusted="true">/);
    assert.match(notes, /<agent-instructions untrusted="true">/);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test("detectProfile: a ban anywhere wins, and symlinked docs are never read", () => {
  const outside = fixture({ "secret.txt": "PRIVATE KEY: we do not accept AI-generated code" });
  const dir = fixture({ "CONTRIBUTING.md": "Mention AI use in the PR.", "AI_POLICY.md": "We do not accept AI-generated contributions." });
  try {
    assert.equal(detectProfile(dir, "x/y").aiPolicy.stance, "ban");
    rmSync(path.join(dir, "AI_POLICY.md"));
    try { symlinkSync(path.join(outside, "secret.txt"), path.join(dir, "AGENTS.md")); } catch { return; /* no symlink privilege */ }
    const p = detectProfile(dir, "x/y");
    assert.equal(p.agentInstructions, null, "a symlink must not pull host files into the prompt");
    assert.equal(p.aiPolicy.stance, "disclose");
  } finally {
    rmSync(dir, { recursive: true, force: true });
    rmSync(outside, { recursive: true, force: true });
  }
});

test("setupPlan: built-in recipes, detected fallbacks, and a key that follows the lockfile", () => {
  const node = fixture({ "package.json": "{}", "yarn.lock": "a@1\n" });
  const py = fixture({ "pyproject.toml": "[project]\nname='x'\n" });
  const bare = fixture({ "README.md": "hi" });
  try {
    assert.match(setupPlan(bare, "vllm-project/vllm")!.commands.join("\n"), /VLLM_USE_PRECOMPILED=1 uv pip install .* --torch-backend=cpu/);
    assert.equal(setupPlan(bare, "vllm-project/vllm")!.persistent, true);
    assert.match(setupPlan(bare, "react/react")!.commands[0], /^yarn install --frozen-lockfile/);
    assert.equal(setupPlan(bare, "pytorch/pytorch"), null);
    assert.match(setupPlan(node, "x/y")!.commands[0], /^yarn install/);
    assert.equal(setupPlan(py, "x/y")!.persistent, true);
    assert.equal(setupPlan(bare, "x/y"), null);
    const plan = setupPlan(node, "x/y")!;
    const before = setupKey(node, plan);
    assert.match(before, /^[0-9a-f]{12}$/);
    assert.equal(setupKey(node, plan), before, "stable for the same lockfile");
    writeFileSync(path.join(node, "yarn.lock"), "a@2\n");
    assert.notEqual(setupKey(node, plan), before, "a changed lockfile is a new environment");
  } finally {
    for (const d of [node, py, bare]) rmSync(d, { recursive: true, force: true });
  }
});

test("built-in profiles: vllm DCO, react CLA, pytorch scope rules", () => {
  const empty = fixture({ "README.md": "hi" });
  try {
    assert.equal(detectProfile(empty, "vllm-project/vllm").dco, true);
    assert.match(detectProfile(empty, "facebook/react").cla!, /Meta Contributor License Agreement/);
    assert.match(detectProfile(empty, "react/react").cla!, /Meta Contributor License Agreement/, "the repository's new name");
    assert.match(detectProfile(empty, "pytorch/pytorch").cla!, /EasyCLA/);
    assert.equal(detectProfile(empty, "other/repo").dco, false);
  } finally {
    rmSync(empty, { recursive: true, force: true });
  }
  assert.deepEqual(outOfScopePaths("pytorch/pytorch", ["torch/nn/modules/linear.py", "aten/src/ATen/native/Linear.cpp", "torch/csrc/api/x.h"]), ["aten/src/ATen/native/Linear.cpp", "torch/csrc/api/x.h"]);
  assert.deepEqual(outOfScopePaths("vllm-project/vllm", ["csrc/x.cu"]), []);
  assert.match(refuseIssue("pytorch/pytorch", "Wrong result in CUDA kernel", "see aten/src/ATen/native/cuda/foo.cu")!, /C\+\+\/CUDA/);
  assert.equal(refuseIssue("pytorch/pytorch", "torch.nn.Linear repr is wrong", "the __repr__ prints the wrong bias"), null);
  assert.equal(refuseIssue("facebook/react", "crash in foo.cpp", ""), null);
  assert.match(cloneEnv("pytorch/pytorch").OPENSRCER_CLONE_SPARSE, /torch test tools/);
  assert.equal(cloneEnv("facebook/react").OPENSRCER_CLONE_SPARSE, undefined);
});
